using System.Diagnostics.CodeAnalysis;
using System.Text.Json.Serialization;
using Intropy.Topology.Validation;

namespace Intropy.Topology;

/// <summary>
/// Identifies a pub/sub topic by its Dapr component and topic names. The backing
/// resource materializes only when a component uses the reference.
/// </summary>
public abstract record TopicRef
{
    /// <summary>The Dapr pubsub component name (DNS-1123 subdomain).</summary>
    public string PubSubName { get; }

    /// <summary>The topic name within the pubsub (DNS-1123 subdomain).</summary>
    public string TopicName { get; }

    /// <summary>The event contract type carried on the topic.</summary>
    public abstract Type ContractType { get; }

    private protected TopicRef(string pubSubName, string topicName)
    {
        PubSubName = NameRules.RequireSubdomain(pubSubName, nameof(pubSubName));
        TopicName = NameRules.RequireSubdomain(topicName, nameof(topicName));
    }
}

/// <summary>
/// A <see cref="TopicRef"/> whose generic argument identifies the event contract. Topology
/// wiring uses the topic names, while <see cref="TopicRef.ContractType"/> exposes the type.
/// </summary>
/// <typeparam name="T">The event contract type published on the topic.</typeparam>
public sealed record TopicRef<T> : TopicRef
{
    /// <inheritdoc />
    public override Type ContractType => typeof(T);

    private TopicRef(string pubSubName, string topicName)
        : base(pubSubName, topicName)
    {
    }

    /// <summary>Declares a topic on a pubsub component.</summary>
    /// <param name="pubSubName">The Dapr pubsub component name (DNS-1123 subdomain).</param>
    /// <param name="topicName">The topic name (DNS-1123 subdomain).</param>
    /// <exception cref="ArgumentException">A name is not a valid DNS-1123 subdomain.</exception>
    public static TopicRef<T> Define(
        [ConstantExpected] string pubSubName,
        [ConstantExpected] string topicName) =>
        new(pubSubName, topicName);
}

/// <summary>
/// Identifies a system-owned connection point and the Dapr binding transport used to
/// materialize it. Direction follows from <c>From</c> and <c>To</c> usage; the binding
/// component name is derived as <c>binding.&lt;connector-name&gt;</c>.
/// </summary>
public sealed record ConnectorRef
{
    /// <summary>The connector's name (DNS-1123 label, e.g. <c>pim</c>).</summary>
    public string Name { get; }

    /// <summary>The local transport — the kind of Dapr binding the connector materializes as during F5 runs.</summary>
    public Transport Transport { get; }

    /// <summary>
    /// The transport shape used after deployment, or <see langword="null"/> when the local
    /// transport also applies to deployed environments.
    /// </summary>
    public Transport? DeployedTransport { get; init; }

    private ConnectorRef(string name, Transport transport)
    {
        Name = name;
        Transport = transport;
    }

    /// <summary>
    /// Declares a connector resolved to a transport — the form <c>intropy system create</c>
    /// emits for the default local-file resolution, where the transport's endpoint (e.g. a
    /// <see cref="FileTransport"/> folder) is the connection itself.
    /// </summary>
    /// <param name="name">The connector's name (DNS-1123 label).</param>
    /// <param name="transport">The kind of Dapr binding the connector materializes as.</param>
    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
    public static ConnectorRef Define([ConstantExpected] string name, Transport transport)
    {
        ArgumentNullException.ThrowIfNull(transport);
        return new ConnectorRef(NameRules.RequireLabel(name, nameof(name)), transport);
    }

    /// <summary>
    /// Declares the value-free transport shape that materializes for deployment. Connection
    /// values remain environment-owned deployment configuration; local F5 runs keep using
    /// <see cref="Transport"/>.
    /// </summary>
    /// <param name="transport">The deployed Dapr binding transport shape.</param>
    /// <returns>A connector reference with the deployed transport set.</returns>
    public ConnectorRef WithDeployed(Transport transport)
    {
        ArgumentNullException.ThrowIfNull(transport);
        return this with { DeployedTransport = transport };
    }
}

/// <summary>
/// The kind of Dapr binding a connector materializes as. All connectivity goes through
/// Dapr — the transport selects the Dapr binding component's <c>spec.type</c>; it never
/// bypasses Dapr. The component name is always derived: <c>binding.&lt;connector-name&gt;</c>.
/// </summary>
[JsonPolymorphic(TypeDiscriminatorPropertyName = "$transport")]
[JsonDerivedType(typeof(FileTransport), "file")]
[JsonDerivedType(typeof(SftpTransport), "sftp")]
public abstract record Transport
{
    private protected Transport()
    {
    }

    /// <summary>The Dapr binding component's <c>spec.type</c> (e.g. <c>bindings.localstorage</c>).</summary>
    public abstract string DaprType { get; }

    /// <summary>Whether the transport can provide input to a component through <c>From</c>.</summary>
    [JsonIgnore]
    public abstract bool SupportsInput { get; }

    /// <summary>Whether the transport can accept component output through <c>To</c>.</summary>
    [JsonIgnore]
    public abstract bool SupportsOutput { get; }

    /// <summary>
    /// Local file transport (<c>bindings.localstorage</c>): reads and writes files in a folder on
    /// the host. The folder is the endpoint. This is the default resolution
    /// <c>intropy system create</c> applies.
    /// </summary>
    /// <param name="rootPath">The folder the binding reads and writes, relative to the SystemHost directory or absolute.</param>
    /// <exception cref="ArgumentException">The root path is null or whitespace.</exception>
    public static Transport File([ConstantExpected] string rootPath) => new FileTransport(rootPath);

    /// <summary>
    /// SFTP transport (<c>bindings.sftp</c>) for deployed environments. Its address,
    /// credentials, and path are supplied by deployment configuration.
    /// </summary>
    public static Transport Sftp() => new SftpTransport();
}

/// <summary>
/// Local file transport: a Dapr binding component of type <c>bindings.localstorage</c> rooted at
/// <see cref="RootPath"/>. The folder is the endpoint.
/// </summary>
public sealed record FileTransport : Transport
{
    /// <inheritdoc />
    public override string DaprType => "bindings.localstorage";

    /// <inheritdoc />
    [JsonIgnore]
    public override bool SupportsInput => true;

    /// <inheritdoc />
    [JsonIgnore]
    public override bool SupportsOutput => true;

    /// <summary>The folder the binding reads and writes, relative to the SystemHost directory or absolute.</summary>
    public string RootPath { get; }

    /// <summary>Creates a local file transport. Prefer <see cref="Transport.File"/>.</summary>
    /// <param name="rootPath">The folder the binding reads and writes.</param>
    /// <exception cref="ArgumentException">The root path is null or whitespace.</exception>
    public FileTransport(string rootPath)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(rootPath);
        RootPath = rootPath;
    }
}

/// <summary>
/// Value-free SFTP output transport: a Dapr binding component of type <c>bindings.sftp</c>.
/// Deployment configuration supplies its address, credentials, and path.
/// </summary>
public sealed record SftpTransport : Transport
{
    /// <inheritdoc />
    public override string DaprType => "bindings.sftp";

    /// <inheritdoc />
    [JsonIgnore]
    public override bool SupportsInput => false;

    /// <inheritdoc />
    [JsonIgnore]
    public override bool SupportsOutput => true;
}

using Intropy.Topology.Model;

namespace Intropy.Topology.Building;

/// <summary>
/// Base class for builders that declare a topology component and its permitted edges.
/// Each derived builder exposes only the operations valid for its component kind, so
/// invalid edges cannot be declared. Fluent methods return the derived builder type,
/// and <see cref="Component"/> provides the typed component declared by the builder.
/// Not thread-safe.
/// </summary>
/// <typeparam name="TSelf">The concrete component builder type.</typeparam>
/// <typeparam name="TComponent">The typed component the builder declares.</typeparam>
public abstract class ComponentBuilder<TSelf, TComponent>
    where TSelf : ComponentBuilder<TSelf, TComponent>
    where TComponent : Component
{
    private protected ComponentBuilder(TComponent component) => Component = component;

    /// <summary>The typed component this builder declares — hold it to reference the block later.</summary>
    public TComponent Component { get; }
}

/// <summary>Fluent builder for an extractor: an edge block that pulls or receives data
/// from an external system and publishes it to at least one topic.</summary>
public sealed class ExtractorBuilder : ComponentBuilder<ExtractorBuilder, ExtractorComponent>
{
    internal ExtractorBuilder(ExtractorComponent component) : base(component) { }

    /// <summary>Declares that the extractor reads from the outside world through a connector.</summary>
    /// <param name="connector">The connector to read from.</param>
    public ExtractorBuilder From(ConnectorRef connector)
    {
        Component.AddConnector(connector, ConnectorDirection.In);
        return this;
    }

    /// <summary>Declares that the extractor publishes to a topic.</summary>
    /// <param name="topic">The topic to publish to.</param>
    public ExtractorBuilder Publishes(TopicRef topic)
    {
        Component.AddPublish(topic);
        return this;
    }

    /// <summary>Declares that the extractor is activated on a cron schedule (standard
    /// five-field cron or a macro such as <c>@daily</c>). Without a schedule the
    /// extractor runs once at host start. Syntax is validated at
    /// <see cref="SystemBuilder.Build"/>; a later call replaces the value.</summary>
    /// <param name="cron">The cron expression.</param>
    /// <exception cref="ArgumentException">The expression is null or whitespace.</exception>
    public ExtractorBuilder WithSchedule(string cron)
    {
        Component.SetSchedule(cron);
        return this;
    }
}

/// <summary>Fluent builder for a loader: an edge block that subscribes to exactly one topic
/// and writes to an external system through a connector; loaders publish nothing.</summary>
public sealed class LoaderBuilder : ComponentBuilder<LoaderBuilder, LoaderComponent>
{
    internal LoaderBuilder(LoaderComponent component) : base(component) { }

    /// <summary>Declares the single topic the loader subscribes to.</summary>
    /// <param name="topic">The topic whose events the loader consumes.</param>
    public LoaderBuilder Subscribes(TopicRef topic)
    {
        Component.AddSubscribe(topic);
        return this;
    }

    /// <summary>Declares that the loader writes to the outside world through a connector.</summary>
    /// <param name="connector">The connector to write to.</param>
    public LoaderBuilder To(ConnectorRef connector)
    {
        Component.AddConnector(connector, ConnectorDirection.Out);
        return this;
    }
}

/// <summary>Fluent builder for a transactional integration: a synchronous block that
/// reads/writes external systems through connectors; it publishes no topics.</summary>
public sealed class TransactionalIntegrationBuilder
    : ComponentBuilder<TransactionalIntegrationBuilder, TransactionalIntegrationComponent>
{
    internal TransactionalIntegrationBuilder(TransactionalIntegrationComponent component)
        : base(component) { }

    /// <summary>Declares that the integration reads from an external system through a connector.</summary>
    /// <param name="connector">The connector to read from.</param>
    public TransactionalIntegrationBuilder From(ConnectorRef connector)
    {
        Component.AddConnector(connector, ConnectorDirection.In);
        return this;
    }

    /// <summary>Declares that the integration writes to an external system through a connector.</summary>
    /// <param name="connector">The connector to write to.</param>
    public TransactionalIntegrationBuilder To(ConnectorRef connector)
    {
        Component.AddConnector(connector, ConnectorDirection.Out);
        return this;
    }
}

using Intropy.Topology.Model;

namespace Intropy.Topology;

/// <summary>
/// Represents a declared topology component and its recorded edges. Declaration methods
/// record intent; <see cref="SystemBuilder.Build"/> performs completeness and
/// cross-component validation. Instances are mutable during declaration and not thread-safe.
/// </summary>
public abstract class Component
{
    /// <summary>The output port name recorded for every <c>Publishes</c> call.</summary>
    internal const string DefaultPort = "default";

    private readonly List<TopicRef> _subscribes = [];
    private readonly List<(string Port, TopicRef Topic)> _publishes = [];
    private readonly List<(ConnectorRef Connector, ConnectorDirection Direction)> _connectors = [];

    private protected Component(string name, ComponentKind kind)
    {
        Name = name;
        Kind = kind;
    }

    /// <summary>The component's name (K8s resource name / Dapr app-id).</summary>
    public string Name { get; }

    /// <summary>The component's block kind.</summary>
    public ComponentKind Kind { get; }

    /// <summary>The cron schedule recorded by <c>WithSchedule</c>; null when the component
    /// runs once at host start. A later call replaces the value. Syntax is validated at
    /// <see cref="SystemBuilder.Build"/>.</summary>
    internal string? ScheduleCall { get; private set; }

    internal IReadOnlyList<TopicRef> SubscribeCalls => _subscribes;

    internal IReadOnlyList<(string Port, TopicRef Topic)> PublishCalls => _publishes;

    internal IReadOnlyList<(ConnectorRef Connector, ConnectorDirection Direction)> ConnectorCalls => _connectors;

    internal void AddSubscribe(TopicRef topic)
    {
        ArgumentNullException.ThrowIfNull(topic);
        _subscribes.Add(topic);
    }

    internal void AddPublish(TopicRef topic)
    {
        ArgumentNullException.ThrowIfNull(topic);
        _publishes.Add((DefaultPort, topic));
    }

    internal void AddConnector(ConnectorRef connector, ConnectorDirection direction)
    {
        ArgumentNullException.ThrowIfNull(connector);
        _connectors.Add((connector, direction));
    }

    internal void SetSchedule(string cron)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(cron);
        ScheduleCall = cron;
    }
}

/// <summary>The declared extractor: an edge block that pulls or receives data from an
/// external system and publishes it. Obtained from the extractor builder's
/// <c>Component</c> property.</summary>
public sealed class ExtractorComponent : Component
{
    internal ExtractorComponent(string name) : base(name, ComponentKind.Extractor) { }
}

/// <summary>The declared loader: an edge block that consumes exactly one topic and writes
/// to an external system. Obtained from the loader builder's <c>Component</c> property.</summary>
public sealed class LoaderComponent : Component
{
    internal LoaderComponent(string name) : base(name, ComponentKind.Loader) { }
}

/// <summary>The declared transactional integration: a synchronous block that reads/writes
/// external systems through connectors. Obtained from the integration builder's
/// <c>Component</c> property.</summary>
public sealed class TransactionalIntegrationComponent : Component
{
    internal TransactionalIntegrationComponent(string name)
        : base(name, ComponentKind.TransactionalIntegration) { }
}

using Intropy.Topology.Model;

namespace Intropy.Topology.Building;

/// <summary>
/// Folds the builder declarations into the immutable model: components in declaration
/// order, resources deduplicated from usage and sorted for determinism. Materialization
/// never fails — structurally broken declarations still materialize (first-seen wins on
/// conflicts) so validation rules can inspect and report the full picture.
/// </summary>
internal static class TopologyMaterializer
{
    public static SystemTopology Materialize(SystemBuilder builder)
    {
        var components = new List<ComponentModel>();
        var topics = new Dictionary<(string PubSub, string Topic), TopicAccumulator>();
        var connectors = new Dictionary<string, ConnectorAccumulator>();

        foreach (var component in builder.Components)
        {
            components.Add(MaterializeComponent(component, topics, connectors));
        }

        return new SystemTopology
        {
            SystemName = builder.SystemName,
            Components = components,
            Topics = topics
                .OrderBy(t => t.Key.PubSub, StringComparer.Ordinal)
                .ThenBy(t => t.Key.Topic, StringComparer.Ordinal)
                .Select(t => new TopicResource
                {
                    PubSubName = t.Key.PubSub,
                    TopicName = t.Key.Topic,
                    ContractTypeName = t.Value.ContractTypeName,
                    Publishers = [.. t.Value.Publishers],
                    Subscribers = [.. t.Value.Subscribers],
                })
                .ToArray(),
            Connectors = connectors
                .OrderBy(c => c.Key, StringComparer.Ordinal)
                .Select(c => new ConnectorResource
                {
                    Name = c.Key,
                    Transport = c.Value.Transport,
                    DeployedTransport = c.Value.DeployedTransport,
                    Directions = [.. c.Value.Directions.Order()],
                    UsedBy = [.. c.Value.UsedBy],
                })
                .ToArray(),
        };
    }

    private static ComponentModel MaterializeComponent(
        Component component,
        Dictionary<(string PubSub, string Topic), TopicAccumulator> topics,
        Dictionary<string, ConnectorAccumulator> connectors)
    {
        var subscribes = new List<TopicSubscription>();
        foreach (var topic in component.SubscribeCalls)
        {
            subscribes.Add(new TopicSubscription
            {
                PubSubName = topic.PubSubName,
                TopicName = topic.TopicName,
            });
            AccumulateTopic(topics, topic).Subscribers.Add(component.Name);
        }

        var publishes = new List<PublishEdge>();
        foreach (var (port, topic) in component.PublishCalls)
        {
            publishes.Add(new PublishEdge
            {
                Port = port,
                PubSubName = topic.PubSubName,
                TopicName = topic.TopicName,
            });
            AccumulateTopic(topics, topic).Publishers.Add(component.Name);
        }

        var connectorEdges = new List<ConnectorEdge>();
        var seenConnectorEdges = new HashSet<(string, ConnectorDirection)>();
        foreach (var (connector, direction) in component.ConnectorCalls)
        {
            AccumulateConnector(connectors, connector, direction).UsedBy.Add(component.Name);
            if (seenConnectorEdges.Add((connector.Name, direction)))
            {
                connectorEdges.Add(new ConnectorEdge { ConnectorName = connector.Name, Direction = direction });
            }
        }

        return new ComponentModel
        {
            Name = component.Name,
            Kind = component.Kind,
            Schedule = component.ScheduleCall,
            Subscribes = subscribes,
            Publishes = publishes,
            Connectors = connectorEdges,
        };
    }

    private static TopicAccumulator AccumulateTopic(
        Dictionary<(string PubSub, string Topic), TopicAccumulator> topics,
        TopicRef topic)
    {
        var key = (topic.PubSubName, topic.TopicName);
        if (!topics.TryGetValue(key, out var accumulator))
        {
            accumulator = new TopicAccumulator(topic.ContractType.FullName ?? topic.ContractType.Name);
            topics[key] = accumulator;
        }

        return accumulator;
    }

    private static ConnectorAccumulator AccumulateConnector(
        Dictionary<string, ConnectorAccumulator> connectors,
        ConnectorRef connector,
        ConnectorDirection direction)
    {
        if (!connectors.TryGetValue(connector.Name, out var accumulator))
        {
            // First-seen wins on identity; conflicting declarations are reported by validation.
            accumulator = new ConnectorAccumulator(connector.Transport, connector.DeployedTransport);
            connectors[connector.Name] = accumulator;
        }

        accumulator.Directions.Add(direction);
        return accumulator;
    }

    private sealed class TopicAccumulator(string contractTypeName)
    {
        public string ContractTypeName { get; } = contractTypeName;
        public SortedSet<string> Publishers { get; } = new(StringComparer.Ordinal);
        public SortedSet<string> Subscribers { get; } = new(StringComparer.Ordinal);
    }

    private sealed class ConnectorAccumulator(Transport transport, Transport? deployedTransport)
    {
        public Transport Transport { get; } = transport;
        public Transport? DeployedTransport { get; } = deployedTransport;
        public HashSet<ConnectorDirection> Directions { get; } = [];
        public SortedSet<string> UsedBy { get; } = new(StringComparer.Ordinal);
    }
}

namespace Intropy.Topology.Model;

/// <summary>
/// One component in the system: an integration block or a container service, together
/// with all of its edges and one activation attribute — an optional cron schedule.
/// Everything else about the workload shape (hosting model, ports,
/// process lifetime) lives in the component's own scaffold, not in the topology.
/// </summary>
public sealed record ComponentModel
{
    /// <summary>The component's name (K8s resource name / Dapr app-id).</summary>
    public required string Name { get; init; }

    /// <summary>The component kind this component was declared as.</summary>
    public required ComponentKind Kind { get; init; }

    /// <summary>The cron schedule that activates the component; null when it runs once
    /// at host start.</summary>
    public required string? Schedule { get; init; }

    /// <summary>Topics the component subscribes to.</summary>
    public required IReadOnlyList<TopicSubscription> Subscribes { get; init; }

    /// <summary>Topics the component publishes to, by output port.</summary>
    public required IReadOnlyList<PublishEdge> Publishes { get; init; }

    /// <summary>Connectors the component uses (explicit From/To usage).</summary>
    public required IReadOnlyList<ConnectorEdge> Connectors { get; init; }
}

using System.Text.Json.Serialization;

namespace Intropy.Topology.Model;

/// <summary>
/// A topic materialized from usage, with its publishing and subscribing component names
/// precomputed in ordinal sort order.
/// </summary>
public sealed record TopicResource
{
    /// <summary>The Dapr pubsub component name.</summary>
    public required string PubSubName { get; init; }

    /// <summary>The topic name.</summary>
    public required string TopicName { get; init; }

    /// <summary>Full name of the event contract type carried on the topic.</summary>
    public required string ContractTypeName { get; init; }

    /// <summary>Names of components publishing to the topic (sorted).</summary>
    public required IReadOnlyList<string> Publishers { get; init; }

    /// <summary>Names of components subscribed to the topic (sorted).</summary>
    public required IReadOnlyList<string> Subscribers { get; init; }
}

/// <summary>A system-owned connector materialized from usage.</summary>
public sealed record ConnectorResource
{
    /// <summary>The connector's name (DNS-1123 label).</summary>
    public required string Name { get; init; }

    /// <summary>The local transport — the kind of Dapr binding the connector materializes during F5 runs.</summary>
    public required Transport Transport { get; init; }

    /// <summary>
    /// The value-free deployed transport shape, or <see langword="null"/> when the local
    /// transport also applies to deployed environments.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Transport? DeployedTransport { get; init; }

    /// <summary>The derived Dapr binding component name: <c>binding.&lt;connector-name&gt;</c>.</summary>
    public string DaprComponentName => $"binding.{Name}";

    /// <summary>The union of directions the connector is used in.</summary>
    public required IReadOnlyList<ConnectorDirection> Directions { get; init; }

    /// <summary>Names of components using the connector (sorted).</summary>
    public required IReadOnlyList<string> UsedBy { get; init; }
}

namespace Intropy.Topology.Model;

/// <summary>
/// The immutable, validated topology of one integration system: its components (in
/// declaration order) and the resources materialized from their usage (sorted).
/// Plain serializable data — generation tooling consumes this model.
/// </summary>
public sealed record SystemTopology
{
    /// <summary>The system's name (DNS-1123 label).</summary>
    public required string SystemName { get; init; }

    /// <summary>All components, in declaration order.</summary>
    public required IReadOnlyList<ComponentModel> Components { get; init; }

    /// <summary>Topics materialized from publish and subscribe edges.</summary>
    public required IReadOnlyList<TopicResource> Topics { get; init; }

    /// <summary>Connectors materialized from connector usage.</summary>
    public required IReadOnlyList<ConnectorResource> Connectors { get; init; }
}

namespace Intropy.Topology.Validation.Rules;

/// <summary>Warning: a component with no edges at all is likely unfinished.</summary>
internal sealed class NoEdgesRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var component in context.Topology.Components)
        {
            var hasEdges =
                component.Subscribes.Count > 0
                || component.Publishes.Count > 0
                || component.Connectors.Count > 0;

            if (!hasEdges)
            {
                yield return new TopologyDiagnostic(
                    DiagnosticSeverity.Warning,
                    "The component has no edges (no subscriptions, publishes, or connectors); it is likely unfinished.",
                    component.Name);
            }
        }
    }
}

/// <summary>
/// A pubsub name must not equal a connector's derived Dapr binding component name
/// (<c>binding.&lt;connector-name&gt;</c>) — both become Dapr Component names in the same
/// Kubernetes namespace.
/// </summary>
internal sealed class PubSubConnectorNameCollisionRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        var pubSubNames = context.Topology.Topics
            .Select(t => t.PubSubName)
            .ToHashSet(StringComparer.Ordinal);

        foreach (var connector in context.Topology.Connectors
            .Where(c => pubSubNames.Contains(c.DaprComponentName)))
        {
            yield return new TopologyDiagnostic(
                DiagnosticSeverity.Error,
                $"The pubsub name '{connector.DaprComponentName}' equals the Dapr binding component name derived from connector '{connector.Name}'; both become Dapr Component names in the same namespace.",
                connector.DaprComponentName);
        }
    }
}

using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using Intropy.Topology.Model;

namespace Intropy.Topology.Generation;

/// <summary>A single generated artifact: a relative path and its text content.</summary>
/// <param name="RelativePath">Path relative to the output root (forward slashes).</param>
/// <param name="Content">The file's text content.</param>
public sealed record GeneratedFile(string RelativePath, string Content);

/// <summary>The artifacts generated for a system: Dapr component YAML and per-component runtime config.</summary>
public sealed class GeneratedArtifacts
{
    /// <summary>Subdirectory holding Dapr component YAML — the value for a sidecar's resources-path.</summary>
    public const string ComponentsDir = "components";

    /// <summary>Subdirectory holding per-component runtime config.</summary>
    public const string ConfigDir = "config";

    internal GeneratedArtifacts(IReadOnlyList<GeneratedFile> files) => Files = files;

    /// <summary>All generated files, in deterministic order.</summary>
    public IReadOnlyList<GeneratedFile> Files { get; }

    /// <summary>Writes every artifact under <paramref name="directory"/>, creating subdirectories.</summary>
    /// <param name="directory">The output root.</param>
    public void WriteTo(string directory)
    {
        ArgumentException.ThrowIfNullOrEmpty(directory);
        foreach (var file in Files)
        {
            var path = Path.Combine(directory, file.RelativePath.Replace('/', Path.DirectorySeparatorChar));
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.WriteAllText(path, file.Content);
        }
    }
}

/// <summary>
/// Turns a validated <see cref="SystemTopology"/> into Dapr components and runtime config
/// for the local run profile: pub/sub backed by Redis Streams, file bindings anchored to the
/// SystemHost directory. Output order is deterministic.
/// </summary>
public static class TopologyGenerator
{
    // Schedule is the only emitted property that is ever null; omitting it keeps
    // unscheduled components' config free of a redundant attribute.
    private static readonly JsonSerializerOptions s_json = new()
    {
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
    };

    /// <summary>Generates the artifacts for a topology.</summary>
    /// <param name="topology">The validated topology.</param>
    /// <returns>The generated artifacts.</returns>
    public static GeneratedArtifacts Generate(SystemTopology topology)
    {
        ArgumentNullException.ThrowIfNull(topology);
        var files = new List<GeneratedFile>();

        foreach (var topic in topology.Topics.Select(t => t.PubSubName).Distinct(StringComparer.Ordinal))
        {
            files.Add(PubSubComponent(topic, topology));
        }

        foreach (var connector in topology.Connectors)
        {
            files.Add(BindingComponent(connector));
        }

        foreach (var component in topology.Components)
        {
            files.Add(ComponentConfig(topology.SystemName, component));
        }

        return new GeneratedArtifacts(files);
    }

    private static GeneratedFile PubSubComponent(string pubSubName, SystemTopology topology)
    {
        var scopes = topology.Components
            .Where(c => c.Subscribes.Any(s => s.PubSubName == pubSubName) || c.Publishes.Any(p => p.PubSubName == pubSubName))
            .Select(c => c.Name)
            .OrderBy(n => n, StringComparer.Ordinal);

        // Redis Streams with consumer groups: an unacked or RETRY'd message is redelivered
        // after the component's redeliverInterval instead of being dropped. Port 6380 because
        // `dapr init` publishes its own dapr_redis on the host's 6379.
        var metadata = new[]
        {
            ("redisHost", "localhost:6380"),
        };
        var yaml = DaprYaml.Component(pubSubName, "pubsub.redis", metadata, scopes);
        return new GeneratedFile($"{GeneratedArtifacts.ComponentsDir}/{pubSubName}.yaml", yaml);
    }

    private static GeneratedFile BindingComponent(ConnectorResource connector)
    {
        var metadata = new List<(string, string)>();
        if (connector.Transport is FileTransport file)
        {
            // Artifacts land in per-run temp dirs and the sidecar's cwd is not guaranteed,
            // so anchor the folder at generation time (cwd = the SystemHost directory).
            metadata.Add(("rootPath", Path.GetFullPath(file.RootPath)));
        }

        var yaml = DaprYaml.Component(
            connector.DaprComponentName, connector.Transport.DaprType, metadata, connector.UsedBy);
        return new GeneratedFile($"{GeneratedArtifacts.ComponentsDir}/{connector.DaprComponentName}.yaml", yaml);
    }

    private static GeneratedFile ComponentConfig(string systemName, ComponentModel component)
    {
        var config = new
        {
            Intropy = new
            {
                System = systemName,
                Component = component.Name,
                Kind = component.Kind.ToString(),
                component.Schedule,
                Subscribes = component.Subscribes.Select(s => new { s.PubSubName, s.TopicName }),
                Publishes = component.Publishes.Select(p => new { p.Port, p.PubSubName, p.TopicName }),
                Connectors = component.Connectors.Select(c => new
                {
                    c.ConnectorName,
                    Direction = c.Direction.ToString(),
                    DaprComponent = $"binding.{c.ConnectorName}",
                }),
            },
        };

        var json = JsonSerializer.Serialize(config, s_json);
        return new GeneratedFile($"{GeneratedArtifacts.ConfigDir}/{component.Name}.intropy.json", json);
    }
}

/// <summary>Minimal, deterministic emitter for Dapr <c>Component</c> YAML.</summary>
internal static class DaprYaml
{
    public static string Component(
        string name,
        string type,
        IEnumerable<(string Key, string Value)> metadata,
        IEnumerable<string> scopes)
    {
        var meta = metadata.ToList();
        var scopeList = scopes.ToList();

        var sb = new StringBuilder();
        sb.Append("apiVersion: dapr.io/v1alpha1\n");
        sb.Append("kind: Component\n");
        sb.Append("metadata:\n");
        sb.Append("  name: ").Append(Quote(name)).Append('\n');
        sb.Append("spec:\n");
        sb.Append("  type: ").Append(Quote(type)).Append('\n');
        sb.Append("  version: v1\n");
        if (meta.Count == 0)
        {
            sb.Append("  metadata: []\n");
        }
        else
        {
            sb.Append("  metadata:\n");
            foreach (var (key, value) in meta)
            {
                sb.Append("  - name: ").Append(Quote(key)).Append('\n');
                sb.Append("    value: ").Append(Quote(value)).Append('\n');
            }
        }

        if (scopeList.Count > 0)
        {
            sb.Append("scopes:\n");
            foreach (var scope in scopeList)
            {
                sb.Append("- ").Append(Quote(scope)).Append('\n');
            }
        }

        return sb.ToString();
    }

    private static string Quote(string value) =>
        $"\"{value.Replace("\\", "\\\\", StringComparison.Ordinal).Replace("\"", "\\\"", StringComparison.Ordinal)}\"";
}

using System.Reflection;
using System.Text.Json;
using System.Text.Json.Serialization;
using Intropy.Topology;
using Intropy.Topology.Model;

namespace Intropy.Topology.Generation;

/// <summary>
/// The non-Aspire backend: the <c>check</c>, <c>graph</c>, and <c>generate</c> CLI verbs over a
/// discovered system. F5 (the Aspire backend) and these verbs consume the same discovered truth.
/// </summary>
public static class IntropyGenerate
{
    private static readonly JsonSerializerOptions s_json = new()
    {
        WriteIndented = true,
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
    };

    /// <summary>Runs a generation CLI verb against the system discovered in <paramref name="assembly"/>.</summary>
    /// <param name="assembly">The assembly declaring the <see cref="ISystemDefinition"/>.</param>
    /// <param name="args">Command-line arguments; <c>args[0]</c> is the verb (check | graph | generate).</param>
    /// <returns>A process exit code.</returns>
    public static Task<int> RunAsync(Assembly assembly, string[] args)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        ArgumentNullException.ThrowIfNull(args);

        var verb = args.Length > 0 ? args[0] : "check";
        return Task.FromResult(verb switch
        {
            "check" => Check(assembly),
            "graph" => Graph(assembly),
            "generate" => Generate(assembly, args),
            _ => Unknown(verb),
        });
    }

    private static int Check(Assembly assembly)
    {
        try
        {
            var discovered = SystemDiscovery.Discover(assembly);
            Console.WriteLine($"ok: '{discovered.Topology.SystemName}' is valid ({discovered.Topology.Components.Count} components).");
            return 0;
        }
        catch (TopologyValidationException ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return 1;
        }
    }

    private static int Graph(Assembly assembly)
    {
        try
        {
            var topology = SystemDiscovery.Discover(assembly).Topology;
            Console.WriteLine(JsonSerializer.Serialize(GraphDocument.From(topology), s_json));
            return 0;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return 1;
        }
    }

    /// <summary>Maps the validated internal model to the topology.intropy.io/v1 interchange contract.</summary>
    private sealed record GraphDocument(
        string ApiVersion,
        string Kind,
        string System,
        IReadOnlyList<GraphComponent>? Components,
        IReadOnlyList<GraphTopic>? Topics,
        IReadOnlyList<GraphConnector>? Connectors)
    {
        public static GraphDocument From(SystemTopology topology) => new(
            "topology.intropy.io/v1",
            "SystemTopology",
            topology.SystemName,
            Optional(topology.Components.Select(GraphComponent.From)),
            Optional(topology.Topics.Select(GraphTopic.From)),
            Optional(topology.Connectors.Select(GraphConnector.From)));
    }

    private sealed record GraphComponent(
        string Name,
        string Kind,
        IReadOnlyList<GraphTopicReference>? Subscribes,
        IReadOnlyList<GraphPublication>? Publishes,
        IReadOnlyList<GraphConnectorUse>? Connectors)
    {
        public static GraphComponent From(ComponentModel component) => new(
            component.Name,
            KebabCase(component.Kind.ToString()),
            Optional(component.Subscribes.Select(t => new GraphTopicReference(t.PubSubName, t.TopicName))),
            Optional(component.Publishes.Select(p => new GraphPublication(
                p.Port == "default" ? null : p.Port, p.PubSubName, p.TopicName))),
            Optional(component.Connectors.Select(c => new GraphConnectorUse(
                c.ConnectorName, Direction(c.Direction)))));
    }

    private sealed record GraphTopicReference(
        [property: JsonPropertyName("pubsub")] string PubSub,
        string Topic);

    private sealed record GraphPublication(
        string? Port,
        [property: JsonPropertyName("pubsub")] string PubSub,
        string Topic);

    private sealed record GraphConnectorUse(string Connector, string Direction);

    private sealed record GraphTopic(
        [property: JsonPropertyName("pubsub")] string PubSub,
        string Topic,
        string Contract,
        IReadOnlyList<string>? Publishers,
        IReadOnlyList<string>? Subscribers)
    {
        public static GraphTopic From(TopicResource topic) => new(
            topic.PubSubName,
            topic.TopicName,
            topic.ContractTypeName,
            Optional(topic.Publishers),
            Optional(topic.Subscribers));
    }

    private sealed record GraphConnector(
        string Name,
        GraphTransport Transport,
        GraphTransport? DeployedTransport,
        IReadOnlyList<string>? Directions,
        IReadOnlyList<string>? UsedBy)
    {
        public static GraphConnector From(ConnectorResource connector) => new(
            connector.Name,
            GraphTransport.From(connector.Transport),
            connector.DeployedTransport is { } deployedTransport ? GraphTransport.From(deployedTransport) : null,
            Optional(connector.Directions.Select(Direction)),
            Optional(connector.UsedBy));
    }

    private sealed record GraphTransport(string Type, bool SupportsInput, bool SupportsOutput)
    {
        public static GraphTransport From(Transport transport) => transport switch
        {
            FileTransport => new("file", transport.SupportsInput, transport.SupportsOutput),
            SftpTransport => new("sftp", transport.SupportsInput, transport.SupportsOutput),
            _ => throw new InvalidOperationException($"Unsupported graph transport '{transport.GetType().Name}'."),
        };
    }

    private static T[]? Optional<T>(IEnumerable<T> values)
    {
        var array = values.ToArray();
        return array.Length > 0 ? array : null;
    }

    private static string Direction(ConnectorDirection direction) =>
        direction == ConnectorDirection.In ? "in" : "out";

    private static string KebabCase(string pascal)
    {
        var builder = new System.Text.StringBuilder(pascal.Length + 4);
        foreach (var c in pascal)
        {
            if (char.IsUpper(c) && builder.Length > 0)
            {
                builder.Append('-');
            }

            builder.Append(char.ToLowerInvariant(c));
        }

        return builder.ToString();
    }

    private static int Generate(Assembly assembly, string[] args)
    {
        var directory = args.Skip(1).FirstOrDefault(a => !a.StartsWith('-')) ?? "./out";

        var discovered = SystemDiscovery.Discover(assembly);
        var artifacts = TopologyGenerator.Generate(discovered.Topology);
        artifacts.WriteTo(directory);

        Console.WriteLine($"generated {artifacts.Files.Count} files to '{directory}':");
        foreach (var file in artifacts.Files)
        {
            Console.WriteLine($"  {file.RelativePath}");
        }

        return 0;
    }

    private static int Unknown(string verb)
    {
        Console.Error.WriteLine($"unknown command '{verb}'. Expected: check | graph | generate.");
        return 2;
    }
}

using System.Net;
using System.Net.Sockets;
using System.Reflection;
using Aspire.Hosting;
using Aspire.Hosting.ApplicationModel;
using CommunityToolkit.Aspire.Hosting.Dapr;
using Intropy.Topology.Generation;
using Intropy.Topology.Model;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;

namespace Intropy.Topology.Aspire;

/// <summary>
/// Runs a discovered topology as a local Aspire application with Dapr sidecars. Components
/// start subscribers before publishers when the topic graph is acyclic, and scheduled
/// components run on their cron ticks.
/// </summary>
public static class IntropyAspire
{
    /// <summary>
    /// Fixed host port for the local Redis backend (generated pub/sub YAML points here).
    /// 6380 rather than the Redis default: `dapr init` publishes its own dapr_redis on 6379.
    /// </summary>
    internal const int RedisPort = 6380;

    /// <summary>
    /// Discovers the system in <paramref name="assembly"/>, generates its artifacts to a temp folder,
    /// builds the Aspire resource graph, and runs it. Requires Docker and the Dapr CLI to be present.
    /// </summary>
    /// <param name="assembly">The assembly declaring the <see cref="ISystemDefinition"/>.</param>
    /// <param name="args">Command-line args passed through to the distributed application builder.</param>
    /// <returns>A process exit code.</returns>
    public static async Task<int> RunAsync(Assembly assembly, string[] args)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        ArgumentNullException.ThrowIfNull(args);

        var discovered = SystemDiscovery.Discover(assembly);

        var generatedRoot = Path.Combine(
            Path.GetTempPath(), "intropy-aspire", $"{discovered.Topology.SystemName}-{Guid.NewGuid():N}");
        TopologyGenerator.Generate(discovered.Topology).WriteTo(generatedRoot);

        var builder = DistributedApplication.CreateBuilder(args);
        Apply(builder, discovered.Topology, generatedRoot);

        var app = builder.Build();
        await app.RunAsync().ConfigureAwait(false);
        return 0;
    }

    /// <summary>
    /// Translates the topology into Aspire resources on <paramref name="builder"/>. Separated from
    /// <see cref="RunAsync"/> so the built model can be inspected in tests without running DCP.
    /// </summary>
    internal static void Apply(
        IDistributedApplicationBuilder builder, SystemTopology topology, string generatedRoot)
    {
        var componentsPath = Path.Combine(generatedRoot, GeneratedArtifacts.ComponentsDir);
        var configDir = Path.Combine(generatedRoot, GeneratedArtifacts.ConfigDir);

        // A plain Redis container rather than AddRedis: the generated pub/sub YAML speaks
        // passwordless to localhost:6380, while AddRedis injects a generated password.
        EnsureHostPortAvailable(RedisPort);
        var redis = builder
            .AddContainer("redis", "docker.io/library/redis", "7")
            .WithEndpoint(port: RedisPort, targetPort: 6379);
        // Everything a sidecar dials during component init. Sidecars must wait for Redis to be
        // *ready* (not merely running) — daprd treats a failed component init as fatal, so racing
        // a still-starting backend kills the sidecar. localhost:6380 is DCP's endpoint proxy,
        // which accepts connections from host start, so the probe must demand a PONG rather
        // than settle for an open socket.
        var redisReadiness = new TcpReadyHealthCheck("localhost", RedisPort, TcpReadyHealthCheck.RedisHandshake);
        WithTcpReadiness(builder, redis, redisReadiness);

        // Filled after the component loop; the hook closure only reads it at runtime.
        var sidecarWaits = new Dictionary<string, string[]>(StringComparer.Ordinal);

        // The Dapr toolkit materializes each sidecar as a separate "<component>-dapr-cli" executable
        // that does not carry wait annotations, so WaitFor cannot gate it. Hold its start here until
        // every backend port answers and, for publishers, until every subscriber sidecar is running.
        builder.Eventing.Subscribe<BeforeResourceStartedEvent>(async (evt, cancellationToken) =>
        {
            if (!DaprSidecarIdentity.IsCli(evt.Resource.Name))
            {
                return;
            }

            await redisReadiness.WaitUntilReadyAsync(TimeSpan.FromMinutes(3), cancellationToken)
                .ConfigureAwait(false);

            if (sidecarWaits.TryGetValue(evt.Resource.Name, out var subscriberSidecars))
            {
                var notifications = evt.Services.GetRequiredService<ResourceNotificationService>();
                foreach (var sidecar in subscriberSidecars)
                {
                    await notifications
                        .WaitForResourceAsync(sidecar, KnownResourceStates.Running, cancellationToken)
                        .ConfigureAwait(false);
                }
            }
        });

        var resources = new Dictionary<string, IResourceBuilder<IResource>>(StringComparer.Ordinal);
        var waiters = new Dictionary<string, Action<IResourceBuilder<IResource>>>(StringComparer.Ordinal);
        var unresolved = new List<string>();
        foreach (var component in topology.Components)
        {
            // Each integration gets its own staged component set: its local files plus the
            // generated system overlay, at a stable inspectable path under obj/.
            var stagedPath = ComponentOverlay.Stage(builder.AppHostDirectory, component.Name, componentsPath);

            var projectPath = ProjectConvention.Resolve(builder.AppHostDirectory, component.Name);
            if (!File.Exists(projectPath))
            {
                unresolved.Add($"{component.Name} (expected {projectPath})");
                continue;
            }

            var project = builder.AddProject(component.Name, projectPath);
            if (component.Schedule is null)
            {
                // The endpoint makes Aspire allocate a port and inject ASPNETCORE_URLS (without it
                // every Kestrel binds the 5000 default) and gives the Dapr sidecar its app-port.
                // A scheduled component is a run-to-completion job that receives no inbound
                // delivery, so it gets neither.
                project = project.WithHttpEndpoint();
            }
            else
            {
                AddRunNowCommand(project, component.Name);
            }

            Wire(project, component, stagedPath, configDir, redis);
            resources[component.Name] = project;
            waiters[component.Name] = dependency => project.WaitFor(dependency);
        }

        RegisterDaprSidecarRecovery(builder, topology, redisReadiness);
        RegisterScheduler(builder, topology);

        if (unresolved.Count > 0)
        {
            throw new InvalidOperationException(
                $"No project found for these components by folder convention: {string.Join(", ", unresolved)}. " +
                "Create the project next to the SystemHost.");
        }

        // Subscribers start first, so a publisher's first message finds a registered
        // subscription. Nobody declares this: it is derived from who publishes and who
        // subscribes each topic. Publish/subscribe cycles cannot be ordered — skip entirely
        // rather than deadlock.
        var precedence = SubscriberPrecedence(topology);
        if (HasCycle(precedence))
        {
            Console.Error.WriteLine(
                "intropy: the topology's topics form a publish/subscribe cycle; " +
                "skipping subscriber-first startup ordering.");
            return;
        }

        foreach (var (publisher, subscribers) in precedence)
        {
            if (!waiters.TryGetValue(publisher, out var wait))
            {
                continue;
            }

            var materialized = subscribers.Where(resources.ContainsKey).ToArray();
            foreach (var subscriber in materialized)
            {
                wait(resources[subscriber]);
            }

            if (materialized.Length > 0)
            {
                sidecarWaits[DaprSidecarIdentity.CliName(publisher)] =
                    [.. materialized.Select(DaprSidecarIdentity.CliName)];
            }
        }
    }

    /// <summary>
    /// Registers the <see cref="ComponentScheduler"/> when any component declares a schedule.
    /// Keyed off <c>Schedule</c>, not the component kind — the scheduler is kind-blind.
    /// </summary>
    private static void RegisterScheduler(IDistributedApplicationBuilder builder, SystemTopology topology)
    {
        var scheduled = topology.Components
            .Where(c => c.Schedule is not null)
            .Select(c => new ScheduledComponent(c.Name, c.Schedule!))
            .ToArray();
        if (scheduled.Length == 0)
        {
            return;
        }

        builder.Services.TryAddSingleton(TimeProvider.System);
        builder.Services.AddSingleton<IReadOnlyList<ScheduledComponent>>(scheduled);
        builder.Services.TryAddSingleton<IResourceLifecycle, AspireResourceLifecycle>();
        builder.Services.AddSingleton<ComponentScheduler>();
        builder.Services.AddHostedService(sp => sp.GetRequiredService<ComponentScheduler>());
    }

    /// <summary>
    /// Registers recovery for long-running components' Dapr sidecars. The normal pre-start gate
    /// prevents the common race; recovery covers the remaining interval where a backend passes
    /// TCP readiness but daprd's component initialization still fails. Scheduled components'
    /// sidecars are excluded: the scheduler owns their stop/start lifecycle.
    /// </summary>
    private static void RegisterDaprSidecarRecovery(
        IDistributedApplicationBuilder builder, SystemTopology topology, IBackendReadiness backendReadiness)
    {
        var schedulerOwned = topology.Components
            .Where(c => c.Schedule is not null)
            .Select(c => DaprSidecarIdentity.CliName(c.Name))
            .ToHashSet(StringComparer.Ordinal);
        builder.Services.AddSingleton(new DaprSidecarRecoveryOptions(schedulerOwned));
        builder.Services.TryAddSingleton(TimeProvider.System);
        builder.Services.TryAddSingleton<IResourceLifecycle, AspireResourceLifecycle>();
        builder.Services.AddSingleton<IResourceStateMonitor, AspireResourceStateMonitor>();
        builder.Services.AddSingleton<IBackendReadiness>(backendReadiness);
        builder.Services.AddSingleton<DaprSidecarRecovery>();
        builder.Services.AddHostedService(sp => sp.GetRequiredService<DaprSidecarRecovery>());
    }

    /// <summary>
    /// A dashboard command that triggers a scheduled component immediately, through the same
    /// path as a cron tick — including the skip when the previous run is still in progress.
    /// </summary>
    private static void AddRunNowCommand(IResourceBuilder<ProjectResource> project, string componentName)
    {
        project.WithCommand(
            name: "intropy-run-now",
            displayName: "Run now",
            executeCommand: async context =>
            {
                var scheduler = context.ServiceProvider.GetRequiredService<ComponentScheduler>();
                await scheduler.TriggerAsync(componentName, "manual run", context.CancellationToken)
                    .ConfigureAwait(false);
                return CommandResults.Success();
            },
            commandOptions: new CommandOptions { IconName = "Play", IconVariant = IconVariant.Filled });
    }

    /// <summary>
    /// Which components each publisher must wait for: every subscriber of every topic it
    /// publishes. Self-loops (a component consuming its own topic) are not orderable edges.
    /// </summary>
    private static Dictionary<string, HashSet<string>> SubscriberPrecedence(SystemTopology topology)
    {
        var precedence = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
        foreach (var topic in topology.Topics)
        {
            foreach (var publisher in topic.Publishers)
            {
                foreach (var subscriber in topic.Subscribers)
                {
                    if (string.Equals(publisher, subscriber, StringComparison.Ordinal))
                    {
                        continue;
                    }

                    if (!precedence.TryGetValue(publisher, out var subscribers))
                    {
                        precedence[publisher] = subscribers = new HashSet<string>(StringComparer.Ordinal);
                    }

                    subscribers.Add(subscriber);
                }
            }
        }

        return precedence;
    }

    private static bool HasCycle(Dictionary<string, HashSet<string>> edges)
    {
        var state = new Dictionary<string, int>(StringComparer.Ordinal); // 1 = visiting, 2 = done

        bool Visit(string node)
        {
            if (state.TryGetValue(node, out var seen))
            {
                return seen == 1;
            }

            state[node] = 1;
            if (edges.TryGetValue(node, out var next) && next.Any(Visit))
            {
                return true;
            }

            state[node] = 2;
            return false;
        }

        return edges.Keys.Any(Visit);
    }

    private static void EnsureHostPortAvailable(int port)
    {
        try
        {
            using var listener = new TcpListener(IPAddress.Loopback, port);
            listener.Start();
        }
        catch (SocketException ex)
        {
            throw new InvalidOperationException(
                $"Redis requires host port {port}, but it is already in use. Stop the conflicting process and retry.", ex);
        }
    }

    private static void WithTcpReadiness(
        IDistributedApplicationBuilder builder,
        IResourceBuilder<ContainerResource> container,
        TcpReadyHealthCheck readiness)
    {
        var key = $"{container.Resource.Name}-tcp-ready";
        builder.Services.AddHealthChecks().AddCheck(key, readiness);
        container.WithHealthCheck(key);
    }

    private static void Wire(
        IResourceBuilder<ProjectResource> project,
        ComponentModel component,
        string resourcesPath,
        string configDir,
        IResourceBuilder<ContainerResource> redis)
    {
        project
            .WithDaprSidecar(sidecar =>
            {
                sidecar.WithOptions(new DaprSidecarOptions
                {
                    AppId = component.Name,
                    ResourcesPaths = [resourcesPath],
                });
                sidecar.WaitFor(redis);
            })
            .WithEnvironment("INTROPY__COMPONENT", component.Name)
            .WithEnvironment("INTROPY__CONFIG", Path.Combine(configDir, $"{component.Name}.intropy.json"))
            .WaitFor(redis);
    }
}

namespace Intropy.Topology.Aspire;

/// <summary>
/// Stages the effective Dapr component set for one integration: everything from its own
/// <c>local/dapr-components/</c> passes through, then the system's generated components overlay
/// it — a generated component with the same <c>metadata.name</c> replaces the local one, new
/// names are added. The staged set lands at a stable, inspectable path under the AppHost's
/// <c>obj/dapr-components/&lt;component&gt;/</c> and is regenerated on every start; the
/// integration's sidecar gets it as its resources path. Standalone runs load the local
/// directory instead — same names, different backing.
/// </summary>
internal static class ComponentOverlay
{
    /// <summary>Stages the component set and returns the staged directory.</summary>
    public static string Stage(string appHostDirectory, string componentName, string generatedComponentsDir)
    {
        var stagedDir = Path.Combine(appHostDirectory, "obj", "dapr-components", componentName);
        if (Directory.Exists(stagedDir))
        {
            Directory.Delete(stagedDir, recursive: true);
        }

        Directory.CreateDirectory(stagedDir);

        // metadata.name -> staged file, so a generated component can replace its local counterpart.
        var stagedByName = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var file in ComponentFiles(ProjectConvention.LocalComponentsDir(appHostDirectory, componentName)))
        {
            var target = Path.Combine(stagedDir, Path.GetFileName(file));
            File.Copy(file, target);
            if (MetadataName(File.ReadAllText(file)) is { } name)
            {
                stagedByName[name] = target;
            }
        }

        foreach (var file in ComponentFiles(generatedComponentsDir))
        {
            var name = MetadataName(File.ReadAllText(file));
            if (name is not null && stagedByName.TryGetValue(name, out var replaced))
            {
                File.Delete(replaced);
            }

            var target = Path.Combine(stagedDir, Path.GetFileName(file));
            File.Copy(file, target, overwrite: true);
            if (name is not null)
            {
                stagedByName[name] = target;
            }
        }

        return stagedDir;
    }

    /// <summary>
    /// The top-level <c>metadata.name</c> of a Dapr resource YAML. Only the unindented
    /// <c>metadata:</c> block qualifies — <c>spec.metadata</c> entries are indented past it.
    /// </summary>
    internal static string? MetadataName(string yaml)
    {
        var lines = yaml.Split('\n');
        for (var i = 0; i < lines.Length; i++)
        {
            if (lines[i].TrimEnd() != "metadata:")
            {
                continue;
            }

            for (var j = i + 1; j < lines.Length && lines[j].StartsWith(' '); j++)
            {
                var entry = lines[j].Trim();
                if (entry.StartsWith("name:", StringComparison.Ordinal))
                {
                    return entry["name:".Length..].Trim().Trim('"', '\'');
                }
            }
        }

        return null;
    }

    private static IEnumerable<string> ComponentFiles(string directory) =>
        Directory.Exists(directory)
            ? Directory.EnumerateFiles(directory)
                .Where(f => f.EndsWith(".yaml", StringComparison.OrdinalIgnoreCase)
                    || f.EndsWith(".yml", StringComparison.OrdinalIgnoreCase))
                .OrderBy(f => f, StringComparer.Ordinal)
            : [];
}

using System.Collections.Concurrent;
using Aspire.Hosting.ApplicationModel;
using Cronos;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace Intropy.Topology.Aspire;

/// <summary>A component the scheduler re-runs: its resource name and cron expression.</summary>
internal sealed record ScheduledComponent(string Name, string Cron);

/// <summary>
/// The scheduler's view of the Aspire resource model: last known states plus start/wait
/// commands. A seam so tick behavior is unit-testable without DCP.
/// </summary>
internal interface IResourceLifecycle
{
    /// <summary>Maintains the last-known-state map; runs for the host's lifetime.</summary>
    Task WatchAsync(CancellationToken cancellationToken);

    /// <summary>Whether the resource can be started: never seen, or in a terminal state.
    /// A non-terminal state means a run is still in progress.</summary>
    bool IsStartable(string resourceName);

    /// <summary>Executes a resource command; false when the command fails or is unavailable.</summary>
    Task<bool> ExecuteAsync(string resourceName, string commandName, CancellationToken cancellationToken);

    /// <summary>Waits for the resource to reach Running; false on timeout.</summary>
    Task<bool> WaitUntilRunningAsync(string resourceName, TimeSpan timeout, CancellationToken cancellationToken);
}

/// <summary>Production <see cref="IResourceLifecycle"/> over the Aspire services.</summary>
internal sealed class AspireResourceLifecycle(
    ResourceCommandService commands,
    ResourceNotificationService notifications) : IResourceLifecycle
{
    private readonly ConcurrentDictionary<string, string?> _states = new(StringComparer.Ordinal);

    public async Task WatchAsync(CancellationToken cancellationToken)
    {
        await foreach (var evt in notifications.WatchAsync(cancellationToken).ConfigureAwait(false))
        {
            _states[evt.Resource.Name] = evt.Snapshot.State?.Text;
        }
    }

    public bool IsStartable(string resourceName)
    {
        var state = _states.GetValueOrDefault(resourceName);
        return state is null || KnownResourceStates.TerminalStates.Contains(state, StringComparer.Ordinal);
    }

    public async Task<bool> ExecuteAsync(string resourceName, string commandName, CancellationToken cancellationToken)
    {
        try
        {
            var result = await commands
                .ExecuteCommandAsync(resourceName, commandName, cancellationToken)
                .ConfigureAwait(false);
            return result.Success;
        }
        catch (Exception) when (!cancellationToken.IsCancellationRequested)
        {
            // Command unavailable in the resource's current state, or the resource is
            // unknown — the caller decides whether to fall back or give up on this tick.
            return false;
        }
    }

    public async Task<bool> WaitUntilRunningAsync(
        string resourceName, TimeSpan timeout, CancellationToken cancellationToken)
    {
        using var deadline = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        deadline.CancelAfter(timeout);
        try
        {
            await notifications
                .WaitForResourceAsync(resourceName, KnownResourceStates.Running, deadline.Token)
                .ConfigureAwait(false);
            return true;
        }
        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
        {
            return false;
        }
    }
}

/// <summary>
/// Re-runs scheduled components on their cron ticks — the run backend's CronJob emulation.
/// Every component also runs once at host start via normal resource auto-start; this
/// service only owns the re-runs. Ticks fire in local time (the developer's wall clock,
/// unlike Kubernetes' UTC default), a tick that lands while the previous run is still in
/// progress is skipped with a warning (concurrencyPolicy: Forbid), and the sidecar is
/// started before the app because a run-to-completion block shuts its sidecar down when
/// it exits.
/// </summary>
internal sealed class ComponentScheduler(
    IReadOnlyList<ScheduledComponent> components,
    IResourceLifecycle lifecycle,
    TimeProvider timeProvider,
    ILogger<ComponentScheduler> logger) : BackgroundService
{
    private static readonly TimeSpan s_sidecarReadyTimeout = TimeSpan.FromMinutes(3);

    private readonly ConcurrentDictionary<string, SemaphoreSlim> _gates = new(StringComparer.Ordinal);

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var loops = new List<Task> { WatchQuietlyAsync(stoppingToken) };
        loops.AddRange(components.Select(component => RunScheduleLoopAsync(component, stoppingToken)));
        await Task.WhenAll(loops).ConfigureAwait(false);
    }

    /// <summary>
    /// Starts the component's sidecar + app resource pair, unless the previous run is still
    /// in progress (skipped with a warning). Shared by cron ticks and the dashboard's
    /// "Run now" command.
    /// </summary>
    internal async Task TriggerAsync(string component, string reason, CancellationToken cancellationToken)
    {
        var gate = _gates.GetOrAdd(component, _ => new SemaphoreSlim(1, 1));
        if (!await gate.WaitAsync(0, cancellationToken).ConfigureAwait(false))
        {
            logger.LogWarning(
                "intropy-schedule: skipping {Reason} for {Component}: a trigger is already executing",
                reason, component);
            return;
        }

        try
        {
            if (!lifecycle.IsStartable(component))
            {
                logger.LogWarning(
                    "intropy-schedule: skipping {Reason} for {Component}: the previous run is still in progress",
                    reason, component);
                return;
            }

            // The run-to-completion block shut its sidecar down when it exited, so bring
            // the sidecar back first — daprd must be accepting connections before the app
            // starts, or the app's first sidecar call fails.
            var sidecar = DaprSidecarIdentity.CliName(component);
            if (lifecycle.IsStartable(sidecar))
            {
                if (!await StartResourceAsync(sidecar, cancellationToken).ConfigureAwait(false))
                {
                    logger.LogError(
                        "intropy-schedule: could not start sidecar {Sidecar}; abandoning {Reason} for {Component}",
                        sidecar, reason, component);
                    return;
                }

                if (!await lifecycle.WaitUntilRunningAsync(sidecar, s_sidecarReadyTimeout, cancellationToken)
                        .ConfigureAwait(false))
                {
                    logger.LogError(
                        "intropy-schedule: sidecar {Sidecar} did not reach Running within {Timeout}; " +
                        "abandoning {Reason} for {Component}",
                        sidecar, s_sidecarReadyTimeout, reason, component);
                    return;
                }
            }

            if (!await StartResourceAsync(component, cancellationToken).ConfigureAwait(false))
            {
                logger.LogError("intropy-schedule: could not start {Component} ({Reason})", component, reason);
                return;
            }

            logger.LogInformation("intropy-schedule: triggered {Component} ({Reason})", component, reason);
        }
        finally
        {
            gate.Release();
        }
    }

    private async Task<bool> StartResourceAsync(string resourceName, CancellationToken cancellationToken)
    {
        // Start is right for a terminal/never-started resource; fall back to Restart to
        // absorb state races between our snapshot and DCP's.
        return await lifecycle.ExecuteAsync(resourceName, KnownResourceCommands.StartCommand, cancellationToken)
                   .ConfigureAwait(false)
               || await lifecycle.ExecuteAsync(resourceName, KnownResourceCommands.RestartCommand, cancellationToken)
                   .ConfigureAwait(false);
    }

    private async Task RunScheduleLoopAsync(ScheduledComponent component, CancellationToken stoppingToken)
    {
        try
        {
            while (!stoppingToken.IsCancellationRequested)
            {
                var now = timeProvider.GetUtcNow();
                var next = CronExpression.Parse(component.Cron).GetNextOccurrence(now, TimeZoneInfo.Local);
                if (next is null)
                {
                    logger.LogWarning(
                        "intropy-schedule: {Component}'s schedule '{Cron}' never fires again; stopping its loop",
                        component.Name, component.Cron);
                    return;
                }

                logger.LogInformation(
                    "intropy-schedule: {Component} next run at {Next:o} ({Cron})",
                    component.Name, next.Value.ToLocalTime(), component.Cron);

                var delay = next.Value - now;
                if (delay > TimeSpan.Zero)
                {
                    await Task.Delay(delay, timeProvider, stoppingToken).ConfigureAwait(false);
                }

                await TriggerAsync(component.Name, "cron tick", stoppingToken).ConfigureAwait(false);
            }
        }
        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
        {
            // Host shutdown.
        }
    }

    private async Task WatchQuietlyAsync(CancellationToken stoppingToken)
    {
        try
        {
            await lifecycle.WatchAsync(stoppingToken).ConfigureAwait(false);
        }
        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
        {
            // Host shutdown.
        }
    }
}

using System.Collections.Concurrent;
using Aspire.Hosting.ApplicationModel;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace Intropy.Topology.Aspire;

/// <summary>A resource-state update consumed by sidecar recovery.</summary>
internal sealed record ResourceStateUpdate(string ResourceName, string? State);

/// <summary>Streams Aspire resource state changes without exposing Aspire's event types.</summary>
internal interface IResourceStateMonitor
{
    IAsyncEnumerable<ResourceStateUpdate> WatchAsync(CancellationToken cancellationToken);
}

/// <summary>Production resource-state monitor over Aspire notifications.</summary>
internal sealed class AspireResourceStateMonitor(ResourceNotificationService notifications) : IResourceStateMonitor
{
    public async IAsyncEnumerable<ResourceStateUpdate> WatchAsync(
        [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken cancellationToken)
    {
        await foreach (var update in notifications.WatchAsync(cancellationToken).ConfigureAwait(false))
        {
            yield return new ResourceStateUpdate(update.Resource.Name, update.Snapshot.State?.Text);
        }
    }
}

/// <summary>
/// Compatibility seam for the executable resource created by CommunityToolkit.Aspire.Hosting.Dapr 13.0.0.
/// The toolkit's public sidecar model does not expose this executable, so audit this convention when
/// upgrading the toolkit.
/// </summary>
internal static class DaprSidecarIdentity
{
    private const string CliSuffix = "-dapr-cli";

    public static string CliName(string componentName) => componentName + CliSuffix;

    public static bool IsCli(string resourceName) => resourceName.EndsWith(CliSuffix, StringComparison.Ordinal);
}

/// <summary>Recovery configuration: which sidecars the scheduler owns and recovery must skip.</summary>
internal sealed record DaprSidecarRecoveryOptions(IReadOnlySet<string> SchedulerOwnedSidecars);

internal sealed class DaprSidecarRecovery(
    IResourceStateMonitor states,
    IResourceLifecycle lifecycle,
    IBackendReadiness backendReadiness,
    DaprSidecarRecoveryOptions options,
    TimeProvider time,
    ILogger<DaprSidecarRecovery> logger) : BackgroundService
{
    private const int MaxAttemptsPerSidecar = 3;
    private static readonly TimeSpan s_backendReadyTimeout = TimeSpan.FromMinutes(3);

    // DCP reports an executable as Running the moment its process launches, not when it is
    // healthy — daprd lives ~1s before a fatal component-init exit. Only a stay in Running at
    // least this long counts as having actually run; a scheduled sidecar that legitimately
    // completes faster costs at most MaxAttemptsPerSidecar spurious restarts.
    private static readonly TimeSpan s_minHealthyRunningDuration = TimeSpan.FromSeconds(10);

    private readonly ConcurrentDictionary<string, int> _attempts = new(StringComparer.Ordinal);
    private readonly ConcurrentDictionary<string, long> _runningSince = new(StringComparer.Ordinal);
    private readonly ConcurrentDictionary<string, SemaphoreSlim> _gates = new(StringComparer.Ordinal);

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        try
        {
            await foreach (var update in states.WatchAsync(stoppingToken).ConfigureAwait(false))
            {
                await HandleStateUpdateAsync(update, stoppingToken).ConfigureAwait(false);
            }
        }
        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
        {
            // Host shutdown.
        }
    }

    internal async Task HandleStateUpdateAsync(ResourceStateUpdate update, CancellationToken cancellationToken)
    {
        if (!DaprSidecarIdentity.IsCli(update.ResourceName))
        {
            return;
        }

        // A scheduled component's sidecar is scheduler-owned: the run-to-completion block shuts
        // its sidecar down after every run and the scheduler restarts it on the next tick,
        // so its exits are lifecycle, not failure — however quick the run.
        if (options.SchedulerOwnedSidecars.Contains(update.ResourceName))
        {
            return;
        }

        if (string.Equals(update.State, KnownResourceStates.Running, StringComparison.Ordinal))
        {
            // Overwrite (not TryAdd): after a recovery restart the fresh instance's clock must
            // start over, or its own early crash would be judged by the previous run's stamp.
            _runningSince[update.ResourceName] = time.GetTimestamp();
            return;
        }

        // A normal scheduled sidecar exits after its app completes — but only a sustained stay
        // in Running proves that, so a component-init crash a moment after launch still recovers.
        var ranHealthily = _runningSince.TryGetValue(update.ResourceName, out var since)
            && time.GetElapsedTime(since) >= s_minHealthyRunningDuration;
        var failedBeforeRunning = string.Equals(update.State, KnownResourceStates.Finished, StringComparison.Ordinal)
            || string.Equals(update.State, KnownResourceStates.Exited, StringComparison.Ordinal);
        if (!string.Equals(update.State, KnownResourceStates.FailedToStart, StringComparison.Ordinal)
            && (!failedBeforeRunning || ranHealthily))
        {
            return;
        }

        var gate = _gates.GetOrAdd(update.ResourceName, _ => new SemaphoreSlim(1, 1));
        if (!await gate.WaitAsync(0, cancellationToken).ConfigureAwait(false))
        {
            return;
        }

        try
        {
            var attempt = _attempts.AddOrUpdate(update.ResourceName, 1, (_, prior) => prior + 1);
            if (attempt > MaxAttemptsPerSidecar)
            {
                logger.LogError(
                    "intropy-dapr: {Sidecar} exhausted {MaxAttempts} recovery attempts; inspect its component configuration",
                    update.ResourceName, MaxAttemptsPerSidecar);
                return;
            }

            logger.LogWarning(
                "intropy-dapr: {Sidecar} terminated before completing component initialization; waiting for backends before recovery attempt {Attempt}/{MaxAttempts}",
                update.ResourceName, attempt, MaxAttemptsPerSidecar);
            await backendReadiness.WaitUntilReadyAsync(s_backendReadyTimeout, cancellationToken).ConfigureAwait(false);

            // FailedToStart normally accepts Restart. Start is a state-race fallback when DCP
            // has already moved the resource to a startable terminal state.
            var recovered = await lifecycle
                .ExecuteAsync(update.ResourceName, KnownResourceCommands.RestartCommand, cancellationToken)
                .ConfigureAwait(false)
                || await lifecycle
                    .ExecuteAsync(update.ResourceName, KnownResourceCommands.StartCommand, cancellationToken)
                    .ConfigureAwait(false);
            if (!recovered)
            {
                logger.LogWarning(
                    "intropy-dapr: recovery command for {Sidecar} was unavailable or failed (attempt {Attempt}/{MaxAttempts})",
                    update.ResourceName, attempt, MaxAttemptsPerSidecar);
            }
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            throw;
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, "intropy-dapr: unable to recover {Sidecar}", update.ResourceName);
        }
        finally
        {
            gate.Release();
        }
    }
}

using Intropy.Topology;

/// <summary>The order-flow system: what exists, and what connects it.</summary>
public sealed class OrderFlowSystem : ISystemDefinition
{
    /// <inheritdoc />
    public string SystemName => "order-flow";

    /// <inheritdoc />
    public void Define(SystemBuilder builder)
    {
        builder.AddExtractor("order-extractor")
            .From(Connectors.OrderExtractorSource)
            .Publishes(Topics.Orders)
            .WithSchedule("* * * * *");
        builder.AddLoader("order-loader")
            .Subscribes(Topics.Orders)
            .To(Connectors.OrderLoaderDestination);
    }
}

