using Intropy.Topology.Building;
using Intropy.Topology.Model;
using Intropy.Topology.Validation;

namespace Intropy.Topology;

/// <summary>
/// Entry point for declaring an integration system's topology. Add components, wire
/// them to topics and connectors, then call <see cref="Build"/> to materialize and
/// validate the immutable <see cref="SystemTopology"/>. Resources (topics, connectors)
/// materialize from usage — there is no <c>AddTopic</c>. Not thread-safe;
/// a second <see cref="Build"/> after further mutation reflects the mutations.
/// </summary>
public sealed class SystemBuilder
{
    private readonly List<Component> _components = [];

    /// <summary>The system's name (DNS-1123 label).</summary>
    public string SystemName { get; }

    private SystemBuilder(string systemName)
    {
        SystemName = systemName;
    }

    internal IReadOnlyList<Component> Components => _components;

    /// <summary>Creates a builder for a named system.</summary>
    /// <param name="systemName">The system's name (DNS-1123 label).</param>
    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
    public static SystemBuilder Create(string systemName) =>
        new(NameRules.RequireLabel(systemName, nameof(systemName)));

    /// <summary>Adds an extractor: pulls data out of an external system and publishes it.</summary>
    /// <param name="name">The component's name (DNS-1123 label).</param>
    public ExtractorBuilder AddExtractor(string name) =>
        new(Register(new ExtractorComponent(NameRules.RequireLabel(name, nameof(name)))));

    /// <summary>Adds a loader: consumes a topic and writes to an external system.</summary>
    /// <param name="name">The component's name (DNS-1123 label).</param>
    public LoaderBuilder AddLoader(string name) =>
        new(Register(new LoaderComponent(NameRules.RequireLabel(name, nameof(name)))));

    /// <summary>Adds a transactional integration.</summary>
    /// <param name="name">The component's name (DNS-1123 label).</param>
    public TransactionalIntegrationBuilder AddTransactionalIntegration(string name) =>
        new(Register(new TransactionalIntegrationComponent(NameRules.RequireLabel(name, nameof(name)))));

    /// <summary>
    /// Materializes and validates the topology. Throws when any error-severity
    /// violation exists, carrying every diagnostic found.
    /// </summary>
    /// <exception cref="TopologyValidationException">The declared topology is invalid.</exception>
    public SystemTopology Build() =>
        TryBuild(out var topology, out var diagnostics)
            ? topology!
            : throw new TopologyValidationException(diagnostics);

    /// <summary>Non-throwing <see cref="Build"/>: returns false with the diagnostics when the topology is invalid.</summary>
    /// <param name="topology">The topology when valid; null otherwise.</param>
    /// <param name="diagnostics">All diagnostics found, including warnings.</param>
    public bool TryBuild(out SystemTopology? topology, out IReadOnlyList<TopologyDiagnostic> diagnostics)
    {
        var candidate = TopologyMaterializer.Materialize(this);
        diagnostics = TopologyRules.Run(this, candidate);
        if (diagnostics.Any(d => d.Severity == DiagnosticSeverity.Error))
        {
            topology = null;
            return false;
        }

        topology = candidate;
        return true;
    }

    /// <summary>Runs validation without throwing; returns all diagnostics including warnings.</summary>
    public IReadOnlyList<TopologyDiagnostic> Validate() =>
        TopologyRules.Run(this, TopologyMaterializer.Materialize(this));

    private T Register<T>(T component) where T : Component
    {
        _components.Add(component);
        return component;
    }
}

using Intropy.Topology.Model;

namespace Intropy.Topology.Validation;

/// <summary>Runs every topology rule and collects the diagnostics.</summary>
internal static class TopologyRules
{
    private static readonly ITopologyRule[] Rules =
    [
        new Rules.DuplicateComponentNameRule(),
        new Rules.EmptySystemRule(),
        new Rules.DuplicatePortRule(),
        new Rules.DuplicateSubscriptionRule(),
        new Rules.TopicContractConflictRule(),
        new Rules.ConnectorConflictRule(),
        new Rules.DeployedTransportCapabilityRule(),
        new Rules.MissingRequiredOutputRule(),
        new Rules.MissingRequiredSubscriptionRule(),
        new Rules.ScheduleExpressionRule(),
        new Rules.UnconsumedTopicRule(),
        new Rules.UnproducedTopicRule(),
        new Rules.NoEdgesRule(),
        new Rules.PubSubConnectorNameCollisionRule(),
    ];

    public static IReadOnlyList<TopologyDiagnostic> Run(SystemBuilder builder, SystemTopology topology)
    {
        var context = new ValidationContext(builder, topology);
        return Rules.SelectMany(rule => rule.Evaluate(context)).ToArray();
    }
}

using Intropy.Topology.Model;

namespace Intropy.Topology.Validation;

/// <summary>Everything a rule can inspect: the raw builder declarations and the materialized model.</summary>
internal sealed record ValidationContext(SystemBuilder Builder, SystemTopology Topology);

/// <summary>One structural/semantic validation rule, evaluated at Build time.</summary>
internal interface ITopologyRule
{
    IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context);
}

namespace Intropy.Topology.Validation.Rules;

/// <summary>Every component needs a unique name.</summary>
internal sealed class DuplicateComponentNameRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        var duplicates = context.Topology.Components
            .GroupBy(c => c.Name, StringComparer.Ordinal)
            .Where(g => g.Count() > 1);

        foreach (var group in duplicates)
        {
            yield return new TopologyDiagnostic(
                DiagnosticSeverity.Error,
                $"The component name '{group.Key}' is declared {group.Count()} times; component names must be unique.",
                group.Key);
        }
    }
}

/// <summary>A system must declare at least one component.</summary>
internal sealed class EmptySystemRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        if (context.Topology.Components.Count == 0)
        {
            yield return new TopologyDiagnostic(
                DiagnosticSeverity.Error,
                "The system declares no components.",
                context.Topology.SystemName);
        }
    }
}

using System.Text.Json;
using Intropy.Topology.Model;

namespace Intropy.Topology.Test.Building;

/// <summary>
/// The living spec: mirrors the SystemHost sample from the README and asserts the full
/// shape of the materialized model.
/// </summary>
public class EndToEndTests
{
    private static class ProductFlow
    {
        public static readonly TopicRef<RawEvent> Raw =
            TopicRef<RawEvent>.Define("product-distribution-pubsub", "product-raw");
    }

    private static class PriceFlow
    {
        public static readonly TopicRef<RawEvent> Raw =
            TopicRef<RawEvent>.Define("product-distribution-pubsub", "price-raw");
    }

    private static readonly ConnectorRef s_pim = ConnectorRef.Define("pim", Transport.File("./test/pim"));
    private static readonly ConnectorRef s_erp = ConnectorRef.Define("erp", Transport.File("./test/erp"));

    private static SystemBuilder DeclareSystem()
    {
        var s = SystemBuilder.Create("product-distribution");

        s.AddExtractor("pim-extractor")
            .From(s_pim)
            .Publishes(ProductFlow.Raw)
            .WithSchedule("*/5 * * * *");

        s.AddTransactionalIntegration("pricing-service")
            .From(s_pim)
            .To(s_erp);

        s.AddLoader("product-loader")
            .Subscribes(ProductFlow.Raw)
            .To(s_erp);

        // An extractor whose source stays a private local component: no From edge.
        s.AddExtractor("price-extractor")
            .Publishes(PriceFlow.Raw);

        // A loader whose destination stays a private local component: no To edge.
        s.AddLoader("price-loader")
            .Subscribes(PriceFlow.Raw);

        return s;
    }

    [Fact]
    public void Build_WithSampleSystem_ShouldMaterializeFullTopology()
    {
        // Act
        var topology = DeclareSystem().Build();

        // Assert: system + components
        Assert.Equal("product-distribution", topology.SystemName);
        Assert.Equal(["pim-extractor", "pricing-service", "product-loader", "price-extractor", "price-loader"],
            topology.Components.Select(w => w.Name));

        var extractor = topology.Components[0];
        Assert.Equal(ConnectorDirection.In, Assert.Single(extractor.Connectors).Direction);
        Assert.Equal("default", Assert.Single(extractor.Publishes).Port);
        Assert.Equal("*/5 * * * *", extractor.Schedule);

        var pricing = topology.Components[1];
        Assert.Null(pricing.Schedule);
        Assert.Equal(
            [("pim", ConnectorDirection.In), ("erp", ConnectorDirection.Out)],
            pricing.Connectors.Select(c => (c.ConnectorName, c.Direction)));

        var loader = topology.Components[2];
        Assert.Equal("product-raw", Assert.Single(loader.Subscribes).TopicName);
        Assert.Equal(("erp", ConnectorDirection.Out),
            (Assert.Single(loader.Connectors).ConnectorName, Assert.Single(loader.Connectors).Direction));

        // Assert: materialized resources
        Assert.Equal(["price-raw", "product-raw"], topology.Topics.Select(t => t.TopicName));
        var raw = topology.Topics.Single(t => t.TopicName == "product-raw");
        Assert.Equal(["pim-extractor"], raw.Publishers);
        Assert.Equal(["product-loader"], raw.Subscribers);
        var priceRaw = topology.Topics.Single(t => t.TopicName == "price-raw");
        Assert.Equal(["price-extractor"], priceRaw.Publishers);
        Assert.Equal(["price-loader"], priceRaw.Subscribers);

        Assert.Equal(["erp", "pim"], topology.Connectors.Select(c => c.Name));
        var erp = topology.Connectors[0];
        Assert.Equal(Transport.File("./test/erp"), erp.Transport);
        Assert.Equal("binding.erp", erp.DaprComponentName);
        Assert.Equal(["pricing-service", "product-loader"], erp.UsedBy);
        var pim = topology.Connectors[1];
        Assert.Equal(Transport.File("./test/pim"), pim.Transport);
        Assert.Equal("binding.pim", pim.DaprComponentName);
        Assert.Equal(["pim-extractor", "pricing-service"], pim.UsedBy);
    }

    [Fact]
    public void Validate_WithSampleSystem_ShouldReportNothing()
    {
        // Act & Assert
        Assert.Empty(DeclareSystem().Validate());
    }

    [Fact]
    public void Serialize_WithSampleSystem_ShouldMatchSnapshot()
    {
        // Byte-exact snapshot of the sample system's serialized model: guards materializer
        // output against unintentional change. Regenerate only on intentional model changes.
        const string expected =
            """{"SystemName":"product-distribution","Components":[{"Name":"pim-extractor","Kind":0,"Schedule":"*/5 * * * *","Subscribes":[],"Publishes":[{"Port":"default","PubSubName":"product-distribution-pubsub","TopicName":"product-raw"}],"Connectors":[{"ConnectorName":"pim","Direction":0}]},{"Name":"pricing-service","Kind":2,"Schedule":null,"Subscribes":[],"Publishes":[],"Connectors":[{"ConnectorName":"pim","Direction":0},{"ConnectorName":"erp","Direction":1}]},{"Name":"product-loader","Kind":1,"Schedule":null,"Subscribes":[{"PubSubName":"product-distribution-pubsub","TopicName":"product-raw"}],"Publishes":[],"Connectors":[{"ConnectorName":"erp","Direction":1}]},{"Name":"price-extractor","Kind":0,"Schedule":null,"Subscribes":[],"Publishes":[{"Port":"default","PubSubName":"product-distribution-pubsub","TopicName":"price-raw"}],"Connectors":[]},{"Name":"price-loader","Kind":1,"Schedule":null,"Subscribes":[{"PubSubName":"product-distribution-pubsub","TopicName":"price-raw"}],"Publishes":[],"Connectors":[]}],"Topics":[{"PubSubName":"product-distribution-pubsub","TopicName":"price-raw","ContractTypeName":"Intropy.Topology.Test.RawEvent","Publishers":["price-extractor"],"Subscribers":["price-loader"]},{"PubSubName":"product-distribution-pubsub","TopicName":"product-raw","ContractTypeName":"Intropy.Topology.Test.RawEvent","Publishers":["pim-extractor"],"Subscribers":["product-loader"]}],"Connectors":[{"Name":"erp","Transport":{"$transport":"file","DaprType":"bindings.localstorage","RootPath":"./test/erp"},"DaprComponentName":"binding.erp","Directions":[1],"UsedBy":["pricing-service","product-loader"]},{"Name":"pim","Transport":{"$transport":"file","DaprType":"bindings.localstorage","RootPath":"./test/pim"},"DaprComponentName":"binding.pim","Directions":[0],"UsedBy":["pim-extractor","pricing-service"]}]}""";

        // Act
        var json = JsonSerializer.Serialize(DeclareSystem().Build());

        // Assert
        Assert.Equal(expected, json);
    }

    [Fact]
    public void Serialize_WithSampleSystem_ShouldRoundTrip()
    {
        // Arrange
        var topology = DeclareSystem().Build();

        // Act
        var json = JsonSerializer.Serialize(topology);
        var deserialized = JsonSerializer.Deserialize<SystemTopology>(json);

        // Assert
        Assert.NotNull(deserialized);
        Assert.Equal(topology.SystemName, deserialized.SystemName);
        Assert.Equal(topology.Components.Count, deserialized.Components.Count);
        Assert.Equal("*/5 * * * *", deserialized.Components[0].Schedule);
        Assert.Equal(["product-raw"], deserialized.Components[2].Subscribes.Select(t => t.TopicName));
        var file = Assert.IsType<FileTransport>(deserialized.Connectors.Single(c => c.Name == "erp").Transport);
        Assert.Equal("./test/erp", file.RootPath);
    }
}

